// Glyph Lite layout - generated by glyph-lite-customize from [layout] in theme.conf.
// Existing panels are left alone; `glyph-lite-layout restore` puts your old setup back.
function trySet(obj, key, value) {
    try { obj[key] = value; } catch (e) { /* not available on this Plasma version */ }
}

var bar = new Panel();
bar.location = "top";
bar.height = 32;
trySet(bar, "floating", true);
trySet(bar, "lengthMode", "fit");
trySet(bar, "alignment", "center");
["org.kde.plasma.pager", "org.kde.plasma.panelspacer", "org.glyphlite.island", "org.kde.plasma.panelspacer", "org.kde.plasma.systemtray"].forEach(function (id) { bar.addWidget(id); });

var dock = new Panel();
dock.location = "bottom";
dock.height = 52;
trySet(dock, "floating", true);
trySet(dock, "lengthMode", "fit");
trySet(dock, "alignment", "center");
["org.kde.plasma.icontasks"].forEach(function (id) { dock.addWidget(id); });
